#[test]
fn true_division_is_correctly_rounded() {
    for (a, b, bits) in TRUE_DIV {
        let (a, b) = (big(a), big(b));
        let got = true_div(IntRef::Big(&a), IntRef::Big(&b)).ok().map(f64::to_bits);
        assert_eq!(got, *bits, "{a} / {b}");
    }
}

