#[test]
fn integer_float_comparison_is_exact() {
    for (n, bits, want) in CMP {
        let n = big(n);
        let f = f64::from_bits(*bits);
        assert_eq!(cmp_int_f64(IntRef::Big(&n), f), *want, "{n} vs {f}");
        if let Some(small) = n.to_i64() {
            assert_eq!(cmp_int_f64(IntRef::Small(small), f), *want, "{n} vs {f}");
        }
    }
}

#[test]
fn operators_follow_python() {
    let n = |i: i64| IntRef::Small(i);
    let b = big("-1180591620717411303424"); // -2**70
    let r = IntRef::Big(&b);
    assert_eq!(floordiv(r, n(7)).unwrap(), big("-168655945816773043347"));
    assert_eq!(modulo(r, n(7)).unwrap(), big("5"));
    assert_eq!(modulo(n(5), IntRef::Big(&b)).unwrap(), big("-1180591620717411303419"));
    assert_eq!(floordiv(n(7), n(-2)).unwrap(), big("-4"));
    assert!(matches!(floordiv(r, n(0)), Err(NumError::ZeroDivision(_))));
    assert_eq!(invert(r), big("1180591620717411303423"));
    assert_eq!(rshift(r, 5000), big("-1"));
    assert_eq!(rshift(n(5), 5000), big("0"));
    assert_eq!(lshift(n(1), 100).unwrap(), big("1267650600228229401496703205376"));
    assert_eq!(pow(n(2), n(100)).unwrap(), big("1267650600228229401496703205376"));
    assert_eq!(pow(n(-1), n(1 << 40)).unwrap(), big("1"));
    assert_eq!(bitwise(Bitwise::And, r, n(-1)), b);
    assert_eq!(bitwise(Bitwise::Or, n(-2), n(1)), big("-1"));
    assert_eq!(bitwise(Bitwise::Xor, r, n(1)), big("-1180591620717411303423"));
    assert_eq!(hash(IntRef::Big(&big("1180591620717411303424"))), 512);
    assert_eq!(hash(n(-1)), -2);
    assert_eq!(bit_length(&big("-1180591620717411303424")), 71);
    assert_eq!(bit_count(&big("-1180591620717411303423")), 70);
}

#[test]
fn string_conversion_limits() {
    let ok = BigInt::from(10).pow(4299u32);
    assert_eq!(big_to_string(&ok).unwrap().len(), 4300);
    let too_long = BigInt::from(10).pow(4300u32);
    let err = big_to_string(&too_long).unwrap_err();
    assert_eq!(
        err.to_string(),
        "Exceeds the limit (4300 digits) for integer string conversion; use sys.set_int_max_str_digits() to increase the limit"
    );
    assert!(big_to_string(&-ok).is_ok());
    let err = parse_digits(&"1".repeat(5000), 10).unwrap_err();
    assert_eq!(
        err.to_string(),
        "Exceeds the limit (4300 digits) for integer string conversion: value has 5000 digits; use sys.set_int_max_str_digits() to increase the limit"
    );
    assert!(parse_digits(&"1".repeat(5000), 16).is_ok());
}
